// Procedural, royalty-free music generated by this repository (CC0): a medieval bed in D dorian
// (drone, plucked lute arpeggios, recorder melody, frame drum). Deterministic: same seed + date -> same audio.
// Sound effects live in sfx.js.
import { rng } from '../sim/prng.js';
import { writeWav } from './wav.js';

const RATE = 48000;
const midi = (n) => 440 * 2 ** ((n - 69) / 12);

/** Karplus-Strong plucked string. */
function pluck(out, start, freq, dur, amp, r) {
  const n = Math.max(2, Math.round(RATE / freq));
  const buf = new Float32Array(n);
  for (let i = 0; i < n; i++) buf[i] = r.float(-1, 1);
  const len = Math.min(out.length - start, Math.round(dur * RATE));
  let idx = 0;
  for (let i = 0; i < len; i++) {
    const a = buf[idx], b = buf[(idx + 1) % n];
    buf[idx] = 0.4985 * (a + b);
    out[start + i] += a * amp * Math.min(1, i / 40);
    idx = (idx + 1) % n;
  }
}

function recorder(out, start, freq, dur, amp) {
  const len = Math.min(out.length - start, Math.round(dur * RATE));
  let ph = 0;
  for (let i = 0; i < len; i++) {
    const t = i / RATE;
    const env = Math.min(1, t / 0.06) * Math.min(1, (dur - t) / 0.12);
    const vib = 1 + 0.004 * Math.sin(2 * Math.PI * 5.2 * t) * Math.min(1, t / 0.3);
    ph += (2 * Math.PI * freq * vib) / RATE;
    const s = Math.sin(ph) + 0.18 * Math.sin(2 * ph) + 0.06 * Math.sin(3 * ph);
    out[start + i] += s * amp * env;
  }
}

function drum(out, start, amp, r) {
  const len = Math.min(out.length - start, Math.round(0.35 * RATE));
  let ph = 0;
  for (let i = 0; i < len; i++) {
    const t = i / RATE;
    const f = 70 + 60 * Math.exp(-t * 30);
    ph += (2 * Math.PI * f) / RATE;
    out[start + i] += (Math.sin(ph) * Math.exp(-t * 9) + r.float(-1, 1) * 0.15 * Math.exp(-t * 40)) * amp;
  }
}

export function makeMusic(seed, date, seconds = 31) {
  const r = rng(seed, 'music', date);
  const N = Math.round(seconds * RATE);
  const L = new Float32Array(N), R = new Float32Array(N);
  const bpm = 92 + r.int(-4, 6), beat = 60 / bpm;
  // D dorian chords: Dm - C - G/B? - Am, voiced as arpeggios
  const progs = [[[50, 57, 62, 65], [48, 55, 60, 64], [43, 55, 59, 62], [45, 52, 57, 60]], [[50, 57, 62, 65], [53, 57, 60, 65], [48, 55, 60, 64], [50, 57, 62, 69]]];
  const prog = r.pick(progs);
  const lute = new Float32Array(N), flute = new Float32Array(N), perc = new Float32Array(N), drone = new Float32Array(N);
  const bars = Math.ceil(seconds / (beat * 4));
  for (let bar = 0; bar < bars; bar++) {
    const ch = prog[bar % prog.length];
    const pattern = [0, 1, 2, 3, 2, 1, 2, 3];
    for (let k = 0; k < 8; k++) {
      const t = (bar * 4 + k * 0.5) * beat;
      const st = Math.round(t * RATE);
      if (st >= N) break;
      pluck(lute, st, midi(ch[pattern[k]] + 12), 1.4, 0.32 + (k === 0 ? 0.1 : 0), r);
    }
    for (const b of [0, 2]) { const st = Math.round((bar * 4 + b) * beat * RATE); if (st < N) drum(perc, st, b === 0 ? 0.5 : 0.32, r); }
    { const st = Math.round((bar * 4 + 3.5) * beat * RATE); if (st < N) drum(perc, st, 0.18, r); }
  }
  // recorder melody from the dorian scale, a motif and its answer
  const scale = [62, 64, 65, 67, 69, 71, 72, 74];
  let deg = 4;
  let t = beat * 8;
  while (t < seconds - 2) {
    const len = r.pick([0.5, 1, 1, 1.5, 2]) * beat;
    deg = Math.max(0, Math.min(scale.length - 1, deg + r.pick([-2, -1, -1, 0, 1, 1, 2])));
    if (r.chance(0.85)) recorder(flute, Math.round(t * RATE), midi(scale[deg] + 12), len * 0.95, 0.09);
    t += len;
  }
  // drone on D and A with a slow swell
  let p1 = 0, p2 = 0;
  for (let i = 0; i < N; i++) {
    const tt = i / RATE;
    p1 += (2 * Math.PI * midi(38)) / RATE; p2 += (2 * Math.PI * midi(45)) / RATE;
    const sw = 0.6 + 0.4 * Math.sin(tt * 0.4);
    drone[i] = (Math.sin(p1) + 0.3 * Math.sin(2 * p1) + 0.6 * Math.sin(p2) + 0.15 * Math.sin(3 * p2)) * 0.06 * sw;
  }
  for (let i = 0; i < N; i++) {
    const tt = i / RATE;
    const fade = Math.min(1, tt / 0.4) * Math.min(1, (seconds - tt) / 1.5);
    L[i] = (lute[i] * 0.8 + flute[i] * 0.6 + perc[i] + drone[i]) * fade;
    R[i] = (lute[i] * 0.6 + flute[i] * 0.8 + perc[i] + drone[i]) * fade;
  }
  return [L, R];
}

export function writeMusic(file, seed, date) { writeWav(file, makeMusic(seed, date), RATE); return file; }
